arguments.command:
cd /workspace && cat > tmp/t5.py <<'PYEOF'
import json, subprocess, sys, random
sys.path.insert(0,'/workspace/submission')
import gateway

random.seed(7)
DIR={"sip:ember@studio.test":["sip:e1@alias.studio.test","tel:+12025550121"],
     "sip:desk@sales.test":["tel:+12025550122"]}
ACC={"s":{"primary":"sip:ember@studio.test","allow":["sip:desk@sales.test"]}}
GW={"edge":{"local_domains":["studio.test","sales.test"],"peers":{}},
    "inside":{"local_domains":[],"peers":{"edge":["studio.test","sales.test"]}}}
LOC={"kind":"local","subject":"s"}
PEER={"kind":"peer","name":"edge"}

bodies=["", "hello", "a\r\nb", "x"*100, "line1\r\n\r\nline2", "tab\there", "\x01".replace("\x01","")]
raws=[]
for b in bodies:
    for extra in ["", "Privacy: id\r\n", "Privacy: none\r\n", "Content-Type: text/plain\r\n",
                  "P-Asserted-Identity: <sip:ember@studio.test>\r\n",
                  "P-Preferred-Identity: <tel:+12025550122>\r\n",
                  "Remote-Party-ID: <sip:e1@alias.studio.test>\r\n"]:
        for frm in ["<sip:ember@studio.test>;tag=q7","<sip:anonymous@anonymous.invalid>",
                    '"Bob Smith" <sip:e1@alias.studio.test>','<tel:+12025550121>']:
            raws.append(("MESSAGE sip:user@relay.test SIP/2.0\r\n"
                         f"From: {frm}\r\nTo: <sip:dest@relay.test>;tag=t1\r\n"
                         "Call-ID: c1\r\nCSeq: 42 MESSAGE\r\n"+extra+
                         "Content-Length: %d\r\n\r\n"%len(b))+b)

jobs=[]
for r in raws:
    jobs.append({"gateway":"edge","ingress":LOC,"trusted_out":True,"raw":r})
    jobs.append({"gateway":"edge","ingress":LOC,"trusted_out":False,"raw":r})
batch={"directory":DIR,"accounts":ACC,"gateways":GW,"jobs":jobs}
out=subprocess.run([sys.executable,"/workspace/submission/gateway.py"],input=json.dumps(batch).encode(),capture_output=True)
res=json.loads(out.stdout)["results"]
acc=0; bad=0
for i,r in enumerate(res):
    if r["status"]!="accept": continue
    acc+=1
    w=r["wire"]
    try:
        q=gateway._parse_request(w)
    except Exception as e:
        bad+=1; print("REPARSE FAIL", i, e, repr(w[:120])); continue
    if q.method!="MESSAGE" or q.ruri!="sip:user@relay.test": bad+=1; print("BAD method/uri",i,q.method,q.ruri)
    if q.to_uri!="sip:dest@relay.test" or q.to_tag!="t1": bad+=1; print("BAD to",i,q.to_uri,q.to_tag)
    if q.call_id!="c1" or q.cseq!="42": bad+=1; print("BAD cid/cseq",i,q.call_id,q.cseq)
    if len(q.body)!=int(w.split("Content-Length: ")[1].split("\r\n")[0]): bad+=1; print("BAD len",i)
    if r["private"] != (q.from_uri=="sip:anonymous@anonymous.invalid" or q.privacy=="id"):
        bad+=1; print("BAD privacy",i,r["private"],q.privacy,q.from_uri)
    if not r["private"] and q.from_uri!=r["identity"]: bad+=1; print("BAD from",i)
    has_pai = any(l.startswith("P-Asserted-Identity:") for l in w.split("\r\n"))
    if has_pai != ((not r["private"]) or jobs[i]["trusted_out"]): bad+=1; print("BAD pai",i,has_pai)
    if has_pai and ("P-Asserted-Identity: <%s>"%r["identity"]) not in w: bad+=1; print("BAD pai val",i)
print("accepted",acc,"bad",bad)
PYEOF
python3 tmp/t5.py
